import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Input, Label, FormGroup, Row, Col } from 'reactstrap';
import Select from 'react-select';
import validator from 'validator';
import CustomButton from '../../../../components/CustomButton';
import { courseStatic, coursesStatic } from '../../../../config/constants';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import colors from 'config/colors';
import Radio from '@material-ui/core/Radio';
import CourseOrSubjectCodeForm from '../../Configuration/CourseOrSubjectCodeForm';
import {
  customFilterOption,
  customGetOptionLabel,
  formResMessage,
  getSelectAllItem,
  infoIconSm,
} from 'utils/commonFunc';

const CourseFormModal = ({
  isModalOpen,
  formModalCloseProp,
  saveCourse,
  course,
  updateCourse,
  courseUpdateSuccess,
  courseCodes,
  refreshCourseCodes,
  batchCourseList,
  schoolCourseList,
}) => {
  const stateObj = {
    data: {
      code: '',
      courseId: 0,
      description: '',
      minimumAttendancePercent: '70',
      name: '',
      sylabusType: 'GPA',
      totalWorkingDays: '',
      school: { schoolId: 0 },
      studyLevel: '',
      status: 'ACTIVE',
    },
    errors: {},
    loading: false,
    addMulti: false,
    courses: [],
  };

  const [stateVal, setState] = useState(stateObj);
  const [showCreateCode, setShowCreateCode] = useState(false);

  useEffect(() => {
    if (course && Object.keys(course).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          code: course.code,
          courseId: course.courseId,
          description: course.description,
          minimumAttendancePercent: course.minimumAttendancePercent,
          name: course.name,
          sylabusType: course.sylabusType,
          totalWorkingDays: course.totalWorkingDays,
          school: { schoolId: course.school.schoolId },
          studyLevel: course.studyLevel,
        },
      }));
    }
  }, [course]);

  const handleSelectChange = selectItem => {
    if (!stateVal.addMulti) {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          name: selectItem ? selectItem?.name : '',
          code: selectItem ? selectItem?.value : '',
          studyLevel: selectItem ? selectItem?.studyLevel : '',
        },
      }));
    } else {
      setState(prevState => ({
        ...prevState,
        courses: selectItem,
      }));
    }
  };

  const handleChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.value },
    }));
  };

  const saveMultipleCourse = async () => {
    for (const key in courses) {
      const el = courses[key];
      const postData = {
        ...data,
        name: el.name,
        studyLevel: el.studyLevel,
        code: el.code,
        status: 'ACTIVE',
      };
      try {
        await saveCourse(postData);
        if (Number(key) + 1 === courses.length) {
          stateReset();
          return courseUpdateSuccess('add');
        }
      } catch (err) {
        setError(err);
      }
    }
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data, addMulti } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (!Object.keys(errors).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      if (data?.courseId) {
        return updateCourse(data)
          .then(() => {
            courseUpdateSuccess('update');
            stateReset();
          })
          .catch(err => setError(err));
      } else {
        if (!addMulti) {
          return saveCourse(data)
            .then(() => {
              courseUpdateSuccess('add');
              stateReset();
            })
            .catch(err => setError(err));
        } else {
          return saveMultipleCourse();
        }
      }
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateReset();
    formModalCloseProp();
  };

  const toggleMulti = canAddMulti => {
    stateReset();
    setState(prevState => ({ ...prevState, addMulti: canAddMulti }));
  };

  const validate = data => {
    const errors = {};
    if (!addMulti && validator.isEmpty(data.code)) {
      errors.code = `${courseStatic} code cannot be empty`;
    }
    if (addMulti && !stateVal.courses.length) {
      errors.name = `Minimum 1 ${courseStatic.toLowerCase()} should be selected`;
    }
    if (!addMulti && validator.isEmpty(data.name)) {
      errors.name = `${courseStatic} cannot be empty`;
    }
    if (validator.isEmpty(data.sylabusType)) {
      errors.sylabusType = 'Syllabus type cannot be empty';
    }
    if (validator.isEmpty(data.totalWorkingDays.toString().trim())) {
      errors.totalWorkingDays = 'Total working days cannot be empty';
    } else if (data.totalWorkingDays && Number(data?.totalWorkingDays) < 100) {
      errors.totalWorkingDays = 'Total working days cannot be less than 100';
    } else if (data.totalWorkingDays && Number(data?.totalWorkingDays) > 300) {
      errors.totalWorkingDays = 'Total working days cannot be more than 300';
    }
    if (validator.isEmpty(data.minimumAttendancePercent.toString().trim())) {
      errors.minimumAttendancePercent = 'Minimum attendance percentage cannot be empty';
    } else if (data.minimumAttendancePercent < 65 || data.minimumAttendancePercent > 100) {
      errors.minimumAttendancePercent = 'Percentage range should be minimum 65% to maximum 100%';
    }
    return errors;
  };

  const { data, errors, loading, addMulti, courses } = stateVal;

  const choiceCard = (checked, label, description, onClick) => (
    <div
      onClick={onClick}
      style={{
        display: 'flex',
        alignItems: 'flex-start',
        gap: 4,
        padding: '8px 12px',
        borderRadius: 8,
        border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
        backgroundColor: checked ? '#F5EDFB' : '#fff',
        cursor: 'pointer',
      }}>
      <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2, marginTop: -2 }} />
      <div>
        <div style={{ fontWeight: 'bold', fontSize: 13 }}>{label}</div>
        {description && <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{description}</div>}
      </div>
    </div>
  );

  const getCourses = () => {
    const existBatchCourses = batchCourseList.map(el => el.code);
    const existSclCourses = schoolCourseList.map(el => el.code);
    let courseNameArr = courseCodes
      ?.filter(dto => {
        return !existBatchCourses?.includes(dto.code) && !existSclCourses?.includes(dto.code);
      })
      ?.map(el => ({ ...el, label: `${el.name} (${el.code})`, value: el?.code }));

    if (courseCodes?.length && addMulti) {
      const selectAllItem =
        courseNameArr?.length > 1 && courseNameArr?.length > courses?.length + 1 && getSelectAllItem();
      courseNameArr = [...courseNameArr];
      if (selectAllItem) {
        courseNameArr = [selectAllItem, ...courseNameArr];
      }
    }
    return courseNameArr;
  };

  const courseNameArr = getCourses();

  const modalDiv = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>
          {data?.courseId ? `UPDATE ${courseStatic.toUpperCase()}` : `ADD ${courseStatic.toUpperCase()} TO SCHOOL`}
        </ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              {!data?.courseId && (
                <Row>
                  <Col sm={4} md={4} lg={4} className="mb-2">
                    {choiceCard(!addMulti, 'Add One', null, () => toggleMulti(false))}
                  </Col>
                  <Col sm={8} md={6} lg={6} className="mb-2">
                    {choiceCard(
                      addMulti,
                      'Add Multiple',
                      `Create multiple ${coursesStatic.toLowerCase()} for school. Adding multiple ${coursesStatic.toLowerCase()} at the same time, will take more time than creating one by one`,
                      () => toggleMulti(true)
                    )}
                  </Col>
                </Row>
              )}
              <Row>
                <Col sm={12} md={12}>
                  <FormGroup>
                    <Label htmlFor="">
                      Configured {addMulti ? coursesStatic : courseStatic} <sup> *</sup>{' '}
                      <CommonTooltip
                        content={`These all are the configured ${courseStatic.toLowerCase()} name list. It can be added to your school`}>
                        {infoIconSm()}
                      </CommonTooltip>
                      {!showCreateCode && (
                        <a
                          style={{ marginLeft: 8, fontSize: 13, color: colors.aTag, cursor: 'pointer' }}
                          onClick={() => setShowCreateCode(true)}>
                          + Create new {courseStatic.toLowerCase()}
                        </a>
                      )}
                    </Label>
                    {showCreateCode ? (
                      <CourseOrSubjectCodeForm
                        isShow
                        formFor="showCourseForm"
                        codeList={courseCodes}
                        toggleLoading={() => {}}
                        hideForm={() => setShowCreateCode(false)}
                        updateSuccess={() => {
                          setShowCreateCode(false);
                          refreshCourseCodes && refreshCourseCodes();
                        }}
                      />
                    ) : (
                      <Select
                        name="name"
                        value={
                          !addMulti
                            ? batchCourseList
                                ?.map(el => ({ value: el.courseId, label: el.name }))
                                ?.find(dto => data.courseId === dto.value) ||
                              courseNameArr?.find(dto => data.code === dto.value) ||
                              null
                            : courses
                        }
                        onChange={(selectItem, { action }) => {
                          if (action === 'clear') {
                            selectItem = [];
                          }
                          const isSelectAllExist =
                            Array.isArray(selectItem) && selectItem?.find(dto => dto.value === 'select_all');
                          if (isSelectAllExist) {
                            const allCourses = courseNameArr.filter(
                              el => el.value !== 'select_all' && !courses.map(mto => mto?.value).includes(el?.value)
                            );
                            selectItem = [...courses, ...allCourses];
                          }
                          handleSelectChange(selectItem);
                        }}
                        options={courseNameArr}
                        isClearable
                        isDisabled={data.courseId}
                        isMulti={addMulti}
                        getOptionLabel={customGetOptionLabel}
                        filterOption={customFilterOption}
                      />
                    )}
                    {errors.name && <span className="err-msg">{errors.name}</span>}
                  </FormGroup>
                </Col>
                {/* Code is auto-generated from the picked class/section (see CourseOrSubjectCodeForm)
                    and still submitted as part of `data` via handleSelectChange - it's just not
                    shown to the admin as a field they manage themselves. */}
                <Col sm={6} md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Total working days<sup> *</sup>
                    </Label>
                    <Input
                      type="number"
                      name="totalWorkingDays"
                      onChange={handleChange}
                      value={data.totalWorkingDays}
                      placeholder="Enter here..."
                      maxLength="3"
                    />
                    {errors.totalWorkingDays && <span className="err-msg">{errors.totalWorkingDays}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Syllabus type <sup> *</sup>{' '}
                      <span style={{ color: 'orange' }}>[Currently available syllabus]</span>
                    </Label>
                    <Input
                      type="text"
                      name="sylabusType"
                      onChange={handleChange}
                      value={data.sylabusType}
                      placeholder="Enter here..."
                      maxLength="20"
                      disabled
                    />
                    {errors.sylabusType && <span className="err-msg">{errors.sylabusType}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Minimum attendance percent days<sup> *</sup>
                    </Label>
                    <Input
                      type="number"
                      name="minimumAttendancePercent"
                      onChange={handleChange}
                      value={data.minimumAttendancePercent}
                      placeholder="E.g: 65 or 70 ..."
                    />
                    {errors.minimumAttendancePercent && (
                      <span className="err-msg">{errors.minimumAttendancePercent}</span>
                    )}
                  </FormGroup>
                </Col>
                <Col sm={6} md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Description<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="description"
                      onChange={handleChange}
                      value={data.description}
                      placeholder="Enter here..."
                      maxLength="100"
                    />
                    {errors.description && <span className="err-msg">{errors.description}</span>}
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{modalDiv}</div>;
};

export default CourseFormModal;
