import React from 'react';
import Checkbox from '@material-ui/core/Checkbox';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import Chip from '@material-ui/core/Chip';
import { Label } from 'reactstrap';
import { CommonLoader } from '../../Common/Loader.jsx';
import { coursesStatic } from 'config/constants.js';

// Shared "pick one or more classes" widget - same shape as StudentPicker so the two flows feel
// consistent: a search box, a checkbox list, and a chip row showing exactly what's selected.
const ClassPicker = ({
  classOptions = [],
  isLoading = false,
  searchText,
  onSearchTextChange,
  selectedMap = {},
  onToggle,
  onClearAll,
  // Classes that can't be unchecked from here (e.g. already assigned and only removable
  // elsewhere) - shown checked but not interactive, same treatment as StudentPicker's
  // disabledStudentIds, so it's clear at a glance why some boxes won't respond to clicks.
  disabledCourseIds = [],
}) => {
  const selectedList = Object.values(selectedMap);
  const disabledSet = new Set(disabledCourseIds);
  const filtered = searchText
    ? classOptions.filter(el => el.label?.toLowerCase().includes(searchText.toLowerCase()))
    : classOptions;

  const selectAllVisible = () => {
    filtered.forEach(cls => {
      if (!disabledSet.has(cls.courseId) && !selectedMap[cls.courseId]) onToggle(cls, true);
    });
  };

  return (
    <div>
      <Label htmlFor="">Search {coursesStatic}</Label>
      <input
        className="form-control"
        placeholder={`Search ${coursesStatic} by name or code`}
        value={searchText}
        onChange={e => onSearchTextChange(e.target.value)}
      />

      <div style={{ marginTop: 12, marginBottom: 8 }}>
        <span style={{ fontWeight: 'bold', fontSize: 13, color: '#6b778a' }}>Selected ({selectedList.length}):</span>{' '}
        {selectedList.length ? (
          <>
            {selectedList.map(cls => {
              const isDisabled = disabledSet.has(cls.courseId);
              return (
                <Chip
                  key={cls.courseId}
                  size="small"
                  label={cls.label}
                  onDelete={isDisabled ? undefined : () => onToggle(cls, false)}
                  style={isDisabled ? { margin: 2, backgroundColor: '#e0e0e0' } : { margin: 2 }}
                />
              );
            })}
            <span
              onClick={onClearAll}
              style={{ marginLeft: 8, fontSize: 12, color: '#c62828', cursor: 'pointer', textDecoration: 'underline' }}>
              Clear all
            </span>
          </>
        ) : (
          <span style={{ fontSize: 12, color: '#9a9a9a' }}>None yet &mdash; check names below to add them</span>
        )}
      </div>

      <div style={{ marginBottom: 5 }}>
        <span onClick={selectAllVisible} style={{ fontSize: 12, color: '#1565c0', cursor: 'pointer' }}>
          Select all shown below
        </span>
      </div>

      <div style={{ maxHeight: 280, overflowY: 'auto', border: '1px solid #eee', borderRadius: 6, padding: 10 }}>
        {isLoading ? (
          <CommonLoader />
        ) : filtered?.length ? (
          filtered.map(cls => {
            const isDisabled = disabledSet.has(cls.courseId);
            return (
              <FormControlLabel
                key={cls.courseId}
                style={{ display: 'flex' }}
                control={
                  <Checkbox
                    size="small"
                    checked={isDisabled || !!selectedMap[cls.courseId]}
                    disabled={isDisabled}
                    onChange={e => onToggle(cls, e.target.checked)}
                  />
                }
                label={
                  <span style={{ fontSize: 13, color: isDisabled ? '#9a9a9a' : undefined }}>
                    {cls.label}
                    {isDisabled ? ' (already assigned)' : ''}
                  </span>
                }
              />
            );
          })
        ) : (
          <div style={{ textAlign: 'center', padding: 10, fontSize: 12, color: '#6b778a' }}>
            No {coursesStatic} found
          </div>
        )}
      </div>
    </div>
  );
};

export default ClassPicker;
