import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import { courseTableHead } from 'variables/general';
import {
  fetchBatchCoursesWithPageService,
  saveCourseService,
  fetchCourseService,
  updateCourseService,
  deleteCourseService,
  fetchSchoolCoursesWithPageService,
  fetchBatchCourseService,
  fetchSchoolCoursesWithoutPageService,
} from 'actions/admin/courses';
import { store } from 'index.js';
import CourseFormModal from './components/CourseFormModal.jsx';
import { formResMessage, getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from '../../../utils/commonFunc.js';
import { showToast } from '../../../actions/admin/auth.js';
import { fetchCourseCodesService } from '../../../actions/admin/config.js';
import { coursesStatic, courseStatic } from '../../../config/constants.js';
import { fetchBatchService, saveBatchService, updateBatchService } from 'actions/admin/batches.js';
import BatchFormModal from '../Batch/components/BatchFormModal.jsx';
import MuiTable from '../Common/MuiTable.jsx';
import Radio from '@material-ui/core/Radio';
import colors from 'config/colors';
import CustomButton from '../../../components/CustomButton';

class CoursePage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      confirmModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      batchClassPageParams: {
        page: 1,
        size: 10,
      },
      fetchCourseType: 'batchCourse',
      employeeId: null,
      selectBatchId: null,
      isBatchModalOpen: false,
      allCourseFetching: false,
      batchCourseFetching: false,
    };
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  fetchCourseCodes = (paramObj = {}) => {
    const { schoolId = 0, refetchAgain = false } = paramObj;
    const sclId = this.state.schoolId || schoolId;
    if (sclId && (!this.props.courseCodes?.length || refetchAgain)) {
      this.props.fetchCourseCodes({
        schoolId: sclId,
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchBatch = async actionType => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && (!this.props.batch || actionType === 'update')) {
      this.props.fetchBatch({
        batchId,
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchBatchCourses = async (paramObj = {}) => {
    const { schoolId = 0, actionType = '', refetchAgain = false } = paramObj;
    const { batchId } = getGlobalCurrentBatchUtils();
    const sclId = schoolId || this.state.schoolId;
    if (sclId && batchId && (!this.props.courseData?.content?.length || actionType === 'update' || refetchAgain)) {
      this.isLoading('batchCourseFetching', true);
      await this.props.fetchBatchCourses({
        schoolId: sclId,
        batchId,
        token: this.props.loggedUserToken,
        pageParams: this.state.batchClassPageParams,
      });
      this.fetchSchoolCoursesWithoutPage();
      this.isLoading('batchCourseFetching', false);
    }
  };

  fetchBatchCourseWithoutPage = (paramObj = {}) => {
    const { schoolId = 0 } = paramObj;
    const sclId = schoolId || this.state.schoolId;
    const { batchId } = getGlobalCurrentBatchUtils();
    if (sclId && batchId && !this.props?.batchCourseList?.length) {
      this.props.fetchBatchCourseWithoutPage({
        schoolId: sclId,
        batchId,
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchBatchTabData = (paramObj = {}) => {
    const { actionType, schoolId = 0 } = paramObj;
    this.fetchBatch();
    this.fetchBatchCourses({ actionType, schoolId });
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId });
      const actionObj = { schoolId: globalSchool?.schoolId };
      this.fetchCourseCodes(actionObj);
      this.fetchBatchCourseWithoutPage(actionObj);
      this.fetchBatchTabData(actionObj); // No need of school for this
    } else {
      this.showWarning('Please select school', 'warning');
    }
  }

  fetchSchoolCourses = async actionType => {
    if (this.state.schoolId && (!this.props?.schCourseData?.content?.length || actionType === 'update')) {
      this.isLoading('allCourseFetching', true);
      await this.props.fetchSchoolCourses({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
        pageParams: this.state.pageParams,
      });
      this.isLoading('allCourseFetching', false);
    }
  };

  fetchSchoolCoursesWithoutPage = (paramObj = {}) => {
    const { refetchAgain = false, actionParam = '' } = paramObj;
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    const { schoolId, batchClassPageParams } = this.state;
    const sclId = schoolId || globalSchool?.schoolId;
    if (sclId && batchId && (!this.props.schoolCourseList?.length || refetchAgain || actionParam === 'add')) {
      this.props.fetchSchoolCoursesWoPage({
        schoolId: sclId,
        batchId,
        token: this.props.loggedUserToken,
        pageParams: batchClassPageParams,
      });
    }
  };

  formModalOpen = () => this.setState({ isBatchModalOpen: false, isModalOpen: true });

  batchFormModalOpen = () => this.setState({ isModalOpen: false, isBatchModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false, isBatchModalOpen: false });
  };

  saveCourse = data => {
    data.school = { schoolId: this.state.schoolId };
    data.status = 16; // Active status
    return this.props.saveCourse({ postData: data, token: this.props.loggedUserToken });
  };

  fetchCourse = courseId => {
    return this.props.fetchCourse({ courseId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateCourse = data => {
    return this.props.updateCourse({ postData: data, token: this.props.loggedUserToken });
  };

  batchUpdateSuccess = actionParam => {
    this.formModalClose();
    this.fetchActivePageBatch('update');
    this.showWarning(
      actionParam === 'add' ? 'Batch Classes added successfully' : 'Batch Classes Updated successfully',
      'success'
    );
  };

  courseUpdateSuccess = actionParam => {
    this.fetchSchoolCoursesWithoutPage({ actionParam });
    this.formModalClose();
    this.fetchActivePageBatch('update');
    this.showWarning(
      actionParam === 'add' ? `${courseStatic} added successfully` : `${courseStatic} Updated successfully`,
      'success'
    );
  };

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  deleteCourse = courseId => {
    return this.props
      .deleteCourse({ courseId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchActivePageBatch('update');
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchActivePageBatch = actionType => {
    if (this.state.fetchCourseType === 'schoolCourse') {
      this.fetchSchoolCourses(actionType);
    } else {
      this.fetchBatchTabData({ actionType });
    }
  };

  fetchPageData = page => {
    const name = this.state.fetchCourseType === 'schoolCourse' ? 'pageParams' : 'batchClassPageParams';
    const existState = this.state[name];
    if (!existState?.page || existState?.page !== page) {
      this.setState(
        {
          [name]: {
            ...this.state?.[name],
            page,
          },
        },
        () => {
          window.scrollTo(0, 0);
          this.fetchActivePageBatch('update');
        }
      );
    }
  };

  handleCheckChange = val => {
    this.setState(
      {
        ...this.state,
        fetchCourseType: val,
      },
      () => {
        if (val === 'schoolCourse') {
          this.fetchSchoolCourses();
          this.fetchCourseCodes({ refetchAgain: true });
        } else {
          this.fetchSchoolCoursesWithoutPage();
          this.fetchBatchCourses();
        }
      }
    );
  };

  handleSelectChange = selectItem => {
    const sVal = selectItem.value;
    if (this.state.selectBatchId !== sVal) {
      this.setState(
        {
          ...this.state,
          selectBatchId: sVal,
        },
        async () => {
          await this.fetchBatch('update');
          this.fetchBatchTabData({ actionType: 'update' });
        }
      );
    }
  };

  saveBatch = async data => {
    const { loggedUserId, loggedUserToken } = this.props;
    data.school = { schoolId: this.state.schoolId };
    await this.props.saveBatch({
      postData: data,
      adminId: loggedUserId,
      token: loggedUserToken,
    });
  };

  updateBatch = data => {
    return this.props.updateBatch({ batchId: data.batchId, postData: data, token: this.props.loggedUserToken });
  };

  render() {
    const { isModalOpen, fetchCourseType, isBatchModalOpen, allCourseFetching, batchCourseFetching } = this.state;
    const {
      //API: fetchBatchCourses => fetchBatchCoursesWithPageService: /api/admin/get-school-course-by-page/
      courseData,
      course,
      //API: fetchSchoolCourses => fetchSchoolCoursesWithPageService: /api/admin/get-school-course-by-page/
      schCourseData,
      courseCodes,
      batch,
      batchCourseList,
      schoolCourseList,
    } = this.props;

    const choiceCard = (checked, label, description, onClick) => (
      <div
        onClick={onClick}
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 4,
          padding: '8px 12px',
          borderRadius: 8,
          border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
          backgroundColor: checked ? '#F5EDFB' : '#fff',
          cursor: 'pointer',
        }}>
        <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2, marginTop: -2 }} />
        <div>
          <div style={{ fontWeight: 'bold', fontSize: 13 }}>{label}</div>
          <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{description}</div>
        </div>
      </div>
    );

    const courseFilter = () => {
      return (
        <>
          <Col sm={4} md={4} lg={4} className="mb-2">
            {choiceCard(
              fetchCourseType === 'batchCourse',
              `BATCH ${coursesStatic.toUpperCase()}`,
              `These are the assigned ${courseStatic.toLowerCase()} list for selected batch`,
              () => this.handleCheckChange('batchCourse')
            )}
          </Col>
          <Col sm={4} md={4} lg={4} className="mb-2">
            {choiceCard(
              fetchCourseType === 'schoolCourse',
              `SCHOOL ${coursesStatic.toUpperCase()}`,
              `These are the common ${courseStatic.toLowerCase()} list that has been created under the school. It can be assigned to any batch.`,
              () => this.handleCheckChange('schoolCourse')
            )}
          </Col>
        </>
      );
    };

    return (
      <div className="content">
        <Row>{courseFilter()}</Row>
        <Row>
          <Col xs={12} className="mb-2 text-right">
            {fetchCourseType === 'schoolCourse' ? (
              <CustomButton onClick={this.formModalOpen} name={`Add ${courseStatic}`} />
            ) : (
              <CustomButton onClick={this.batchFormModalOpen} name={`Assign ${courseStatic} To Batch`} />
            )}
          </Col>
        </Row>
        <Row>
          <Col xs={12}>
            <MuiTable
              tableHeaders={courseTableHead.filter(
                fto => fto !== 'Action' || (fto === 'Action' && fetchCourseType === 'schoolCourse')
              )}
              tableBodyData={fetchCourseType === 'schoolCourse' ? { ...schCourseData } : { ...courseData }}
              bodyColumns={[
                'name',
                'sylabusType',
                'totalWorkingDays',
                'minimumAttendancePercent',
                'studyLevel',
                fetchCourseType === 'schoolCourse' ? 'action' : null,
              ]}
              dropDownActions={['edit']}
              idName="courseId"
              fetchItem={this.fetchCourse}
              deleteItem={this.deleteCourse}
              fetchPageData={this.fetchPageData}
              isLoading={
                (fetchCourseType === 'schoolCourse' && allCourseFetching) ||
                (fetchCourseType === 'batchCourse' && batchCourseFetching)
              }
            />
          </Col>
        </Row>
        <CourseFormModal
          isModalOpen={isModalOpen}
          courseCodes={courseCodes}
          formModalCloseProp={this.formModalClose}
          saveCourse={this.saveCourse}
          course={course}
          updateCourse={this.updateCourse}
          courseUpdateSuccess={this.courseUpdateSuccess}
          refreshCourseCodes={() => this.fetchCourseCodes({ refetchAgain: true })}
          batchCourseList={batchCourseList}
          schoolCourseList={schoolCourseList}
        />
        <BatchFormModal
          isModalOpen={isBatchModalOpen}
          formModalCloseProp={this.formModalClose}
          saveBatch={this.saveBatch}
          batch={batch}
          updateBatch={this.updateBatch}
          batchUpdateSuccess={this.batchUpdateSuccess}
          disableBatch={true}
          removeOptional={true}
          heading="UPDATE BATCH CLASS"
          showWarning={this.showWarning}
          // courses={batchCourseList}
          batchCourseList={batchCourseList}
          courses={schoolCourseList}
          formAction="UPDATE"
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    courseData: state.courses.courseData,
    schCourseData: state.courses.schCourseData,
    empCourseList: state.courses.empCourseList,
    course: state.courses.course,
    employees: state.employees.employeeList,
    // Config
    courseCodes: state.config.courseCodes,
    // Batch
    batch: state.batches.batch?.batchId ? state.batches.batch : null,
    batchCourseList: state.courses.batchCourseList,
    schoolCourseList: state.courses?.courseList || [],
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchCourseCodes: data => dispatch(fetchCourseCodesService(data)),

    fetchSchoolCourses: data => dispatch(fetchSchoolCoursesWithPageService(data)),
    fetchSchoolCoursesWoPage: data => dispatch(fetchSchoolCoursesWithoutPageService(data)),
    fetchBatchCourses: data => dispatch(fetchBatchCoursesWithPageService(data)),
    fetchBatchCourseWithoutPage: data => dispatch(fetchBatchCourseService(data)),
    saveCourse: data => dispatch(saveCourseService(data)),
    fetchCourse: data => dispatch(fetchCourseService(data)),
    updateCourse: data => dispatch(updateCourseService(data)),
    deleteCourse: data => dispatch(deleteCourseService(data)),

    fetchBatch: data => dispatch(fetchBatchService(data)),
    saveBatch: data => dispatch(saveBatchService(data)),
    updateBatch: data => dispatch(updateBatchService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(CoursePage);
