import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Input, Label, FormGroup, Row, Col } from 'reactstrap';
import Select from 'react-select';
import moment from 'moment';
import validator from 'validator';
import CustomButton from '../../../../components/CustomButton';
import {
  formResMessage,
  getCurrentYearBatchUtils,
  setGlobalCurrentBatchUtils,
  setGlobalActualCurrentBatchUtils,
  formCourseSelectList,
  infoIconSm,
} from '../../../../utils/commonFunc';
import { coursesStatic, courseStatic } from '../../../../config/constants';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import ClassPicker from 'views/admin/Fees/components/ClassPicker.jsx';

const stateObj = {
  data: {
    school: { schoolId: 0 },
    batchId: 0,
    name: '',
    startYear: '',
    endYear: '',
    courses: [],
  },
  errors: {},
  loading: false,
};
const BatchFormModal = props => {
  const {
    isModalOpen,
    formModalCloseProp,
    courses,
    saveBatch,
    batch,
    updateBatch,
    batchUpdateSuccess,
    disableBatch = false,
    removeOptional = false,
    heading,
    formAction,
    batchCourseList,
    // showWarning = undefined,
  } = props;

  const [stateVal, setState] = useState(stateObj);
  const [courseSearchText, setCourseSearchText] = useState('');

  useEffect(() => {
    stateReset();
  }, []);

  const cArr =
    batchCourseList?.map(item => ({
      isFixed: true,
      label: item.name,
      value: item.courseId,
      courseId: item.courseId,
    })) || [];

  useEffect(() => {
    if (batch && Object.keys(batch).length && formAction !== 'ADD') {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          school: { schoolId: batch.school.schoolId },
          batchId: batch.batchId,
          name: batch.name,
          startYear: batch.startYear,
          endYear: batch.endYear,
          courses: cArr || [],
        },
      }));
    }
  }, [isModalOpen, batch]);

  const courseArr = formCourseSelectList(courses?.filter(fto => !cArr.find(el => el.courseId === fto.courseId)));
  // Full pick-list for the checkbox picker below: already-assigned classes (locked/disabled)
  // plus the ones still available to add.
  const classOptions = [...cArr, ...(courseArr || [])];
  const disabledCourseIds = cArr.map(el => el.courseId);

  const renderYears = () => {
    let stYear = 0;
    let yearArr = [];
    if (moment().month() < 8) {
      stYear = parseInt(moment(new Date()).format('YYYY'), 10) - 1;
    } else {
      stYear = parseInt(moment(new Date()).format('YYYY'), 10);
    }
    if (stYear) {
      yearArr = new Array(3).fill(stYear).map((item, i) => ({ label: item + i, value: item + i }));
    }
    // yearArr.push({ label: '2021', value: 2021 });
    return yearArr;
  };

  const handleChange = e => {
    e.persist();
    const { name } = e.target;
    const val = e.target.value;
    if (!isNaN(val)) {
      setState(prevState => ({
        ...prevState,
        data: { ...prevState.data, [name]: val },
      }));
    }
    if (!isNaN(val) && name === 'startYear' && val.length === 4) {
      setState(prevState => ({
        ...prevState,
        data: { ...prevState.data, endYear: parseInt(val, 10) + 1 },
      }));
    }
  };

  const handleSelectChange = (name, selectItem) => {
    if (name === 'startYear') {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          startYear: selectItem.value,
          endYear: selectItem.value + 1,
        },
      }));
    } else {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          [name]: selectItem,
        },
      }));
    }
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (Object.keys(errors).length === 0) {
      setState(prevState => ({ ...prevState, loading: true }));
      data.name = `${data.startYear} - ${data.endYear}`;
      if (data?.batchId) {
        data.courses = data?.courses?.filter(el => !el?.isFixed);
        return updateBatch(data)
          .then(() => {
            stateReset();
            batchUpdateSuccess('update');
          })
          .catch(err => stateError(err));
      } else {
        return saveBatch(data)
          .then(batch => {
            /* Setting current batch */
            const { startYear } = getCurrentYearBatchUtils();
            if (batch?.startYear === startYear) {
              const bData = {
                batchId: batch.batchId,
                startYear: batch.startYear,
                endYear: batch.endYear,
              };
              setGlobalCurrentBatchUtils(bData);
              setGlobalActualCurrentBatchUtils(bData);
            }
            /* Setting current batch end */
            stateReset();
            batchUpdateSuccess('add');
          })
          .catch(err => stateError(err));
      }
    }
  };

  const stateError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateReset();
    if (disableBatch) {
      const value = data?.courses?.filter(v => v.isFixed);
      handleSelectChange('courses', value);
    }
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (validator.isEmpty(data.startYear.toString().trim())) {
      errors.startYear = 'Start year cannot be empty';
    } else if (data.startYear.toString().trim().length !== 4) {
      errors.startYear = 'Start year is Invalid';
    }
    if (validator.isEmpty(data.endYear.toString().trim())) {
      errors.endYear = 'End year cannot be empty';
    } else if (data.endYear.toString().trim().length !== 4) {
      errors.endYear = 'End year is Invalid';
    } else if (
      data.startYear.toString().trim() < data.endYear.toString().trim() &&
      parseInt(data.startYear, 10) + 1 !== parseInt(data.endYear, 10)
    ) {
      errors.endYear = 'End year can be 1 year greater than Start year';
    }
    if (data.startYear && data.endYear && data.startYear >= data.endYear) {
      errors.endYear = "End year shouldn't be less or equal to start year";
    }
    if (removeOptional && data.courses.length === 0) {
      errors.courses = `Minimum 1 ${courseStatic} should be selected`;
    }
    return errors;
  };

  const { data, errors, loading } = stateVal;

  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{heading || (data.batchId ? 'UPDATE BATCH' : 'ADD BATCH')}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <Row>
                <Col sm={6} md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Start year<sup> *</sup>
                    </Label>
                    <Select
                      name="startYear"
                      value={data.startYear ? { label: data.startYear, value: data.startYear } : null}
                      onChange={value => handleSelectChange('startYear', value)}
                      options={renderYears()}
                      isDisabled={!!disableBatch}
                    />
                    {errors.startYear && <span className="err-msg">{errors.startYear}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      End year <sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="endYear"
                      onChange={handleChange}
                      value={data.endYear}
                      // placeholder="Select start year to auto select this..."
                      maxLength="4"
                      readOnly
                    />
                    {errors.endYear && <span className="err-msg">{errors.endYear}</span>}
                  </FormGroup>
                </Col>
                {disableBatch && (
                  <Col sm={12} md={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Assign {coursesStatic}{' '}
                        {!removeOptional && <span style={{ color: 'grey', marginRight: 5 }}>(Optional)</span>}
                        {!courses?.length && (
                          <CommonTooltip
                            content={`These are the list of the ${coursesStatic.toLowerCase()} that created under school. If the below list is empty, Do create new ${courseStatic.toLowerCase()} under School ${coursesStatic.toLowerCase()}`}>
                            {infoIconSm()}
                          </CommonTooltip>
                        )}
                        {data?.courses?.length > 0 && (
                          <CommonTooltip
                            content={`Assigned ${coursesStatic.toLowerCase()} can't be deleted, Please contact school admin to delete`}>
                            {infoIconSm()}
                          </CommonTooltip>
                        )}
                      </Label>
                      <ClassPicker
                        classOptions={classOptions}
                        searchText={courseSearchText}
                        onSearchTextChange={setCourseSearchText}
                        selectedMap={Object.fromEntries((data.courses || []).map(el => [el.courseId, el]))}
                        disabledCourseIds={disabledCourseIds}
                        onToggle={(cls, checked) => {
                          const nextCourses = checked
                            ? [...data.courses, cls]
                            : data.courses.filter(el => el.courseId !== cls.courseId);
                          handleSelectChange('courses', nextCourses);
                        }}
                        onClearAll={() => handleSelectChange('courses', cArr)}
                      />
                      {errors.courses && <span className="err-msg">{errors.courses}</span>}
                    </FormGroup>
                  </Col>
                )}
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} name="Save" />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default BatchFormModal;
